WITH cleaned AS (SELECT *, IF(is_remote, 'Yes', 'No') is_remote_label, COALESCE(job_title, 'NONE') resolved_job_title FROM employees WHERE hire_date >= TO_DATE('2023-03-26') AND level IS DISTINCT FROM 'L3'), enriched AS (SELECT s.*, p.job_title AS employee_job_title, p.email AS employee_email, p.salary AS employee_salary FROM cleaned s INNER JOIN employees p ON s.manager_id = p.id), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY level, employee_job_title ORDER BY employee_salary DESC, id) AS row_num FROM enriched) ranked WHERE row_num = 1), latest_employees AS (SELECT * FROM latest QUALIFY RANK() OVER (PARTITION BY employee_job_title ORDER BY salary DESC) = 1) SELECT id, job_title, salary, hire_date, level, employee_job_title, employee_email FROM latest_employees ORDER BY hire_date DESC, job_title;
